insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('bmlt-bloodbank1-practice-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"The ABO blood group system was discovered by:","translation":"","options":["Karl Landsteiner","Louis Pasteur","Robert Koch","Edward Jenner"],"correctIndex":0,"explanation":"Landsteiner described the ABO blood groups in 1900–1901.","explanationNe":"कार्ल ल्यान्डस्टाइनरले ABO blood group प्रणाली पत्ता लगाएका थिए।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"The A antigen is present on red cells of blood group:","translation":"","options":["A and AB","B and O","O only","B only"],"correctIndex":0,"explanation":"Group A and AB red cells express A antigen.","explanationNe":"A र AB समूहका RBC मा A antigen हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"A person with blood group O normally has which antibodies in plasma?","translation":"","options":["Anti-A and anti-B","Anti-D only","No ABO antibodies","Anti-A only"],"correctIndex":0,"explanation":"Group O red cells lack A and B antigens, while plasma generally contains both antibodies.","explanationNe":"O समूहको RBC मा A/B antigen हुँदैन र plasma मा सामान्यतया anti-A तथा anti-B हुन्छन्।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"The Rh D antigen is clinically important because it is:","translation":"","options":["Highly immunogenic","Present only in platelets","Destroyed by room temperature","An ABO antibody"],"correctIndex":0,"explanation":"D antigen can stimulate clinically significant anti-D formation.","explanationNe":"D antigen ले शरीरमा महत्वपूर्ण anti-D antibody बनाउन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"A person whose red cells lack the D antigen is described as:","translation":"","options":["Rh negative","AB positive","Group O only","Bombay phenotype"],"correctIndex":0,"explanation":"Rh-negative status means the D antigen is absent on red cells.","explanationNe":"RBC मा D antigen नभए Rh negative भनिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"The major purpose of pre-transfusion compatibility testing is to:","translation":"","options":["Reduce the risk of immune haemolytic transfusion reactions","Increase haemoglobin before collection","Sterilise donor blood","Determine platelet count only"],"correctIndex":0,"explanation":"Compatibility testing detects clinically significant incompatibility before transfusion.","explanationNe":"रगत चढाउनुअघि असंगति पत्ता लगाएर immune haemolysis को जोखिम घटाउनु यसको उद्देश्य हो।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"The major crossmatch tests donor red cells against:","translation":"","options":["Recipient serum or plasma","Donor urine","Recipient saliva","Donor platelet concentrate"],"correctIndex":0,"explanation":"The major crossmatch checks for recipient antibodies reacting with donor red cells.","explanationNe":"Major crossmatch मा बिरामीको serum/plasma र donor RBC प्रतिक्रिया जाँचिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"The minor crossmatch traditionally tests donor serum against:","translation":"","options":["Recipient red cells","Donor red cells","Recipient urine","Recipient platelets"],"correctIndex":0,"explanation":"The minor crossmatch evaluates donor plasma antibodies against recipient cells; many modern systems do not routinely require it.","explanationNe":"Minor crossmatch मा donor serum र recipient RBC जाँचिन्छ; आधुनिक प्रणालीमा यो सधैँ आवश्यक हुँदैन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"The direct antiglobulin test (DAT) detects:","translation":"","options":["Antibody or complement attached to red cells in vivo","Free glucose in plasma","Platelet aggregation","Serum sodium"],"correctIndex":0,"explanation":"DAT detects immunoglobulin and/or complement coating red cells inside the body.","explanationNe":"DAT ले शरीरभित्रै RBC मा टाँसिएको antibody वा complement पत्ता लगाउँछ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"The indirect antiglobulin test (IAT) is used to detect:","translation":"","options":["Free red-cell antibodies in serum or plasma","Bacteria in blood culture","Haemoglobin in urine","Platelet morphology"],"correctIndex":0,"explanation":"IAT detects circulating antibodies that can react with red-cell antigens in vitro.","explanationNe":"IAT ले serum/plasma मा रहेका RBC विरुद्धका antibody पत्ता लगाउँछ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"The universal red-cell donor type in an emergency, when appropriate protocols allow, is:","translation":"","options":["O negative","AB positive","A positive","B negative"],"correctIndex":0,"explanation":"O negative red cells lack A, B and D antigens, but emergency release must follow local policy.","explanationNe":"O negative RBC मा A, B र D antigen हुँदैन; emergency transfusion पनि स्थानीय protocol अनुसार हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"The universal plasma donor in the ABO system is:","translation":"","options":["AB","O","A","B"],"correctIndex":0,"explanation":"AB plasma lacks anti-A and anti-B antibodies.","explanationNe":"AB plasma मा anti-A र anti-B हुँदैन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Packed red blood cells are primarily given to:","translation":"","options":["Improve oxygen-carrying capacity","Correct isolated low platelet count","Replace clotting factor VIII only","Treat dehydration alone"],"correctIndex":0,"explanation":"Red-cell components increase haemoglobin and oxygen delivery when clinically indicated.","explanationNe":"Packed RBC ले आवश्यक अवस्थामा haemoglobin र oxygen बोक्ने क्षमता बढाउँछ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"Platelet concentrates are mainly indicated for:","translation":"","options":["Severe thrombocytopenia or platelet dysfunction with bleeding risk","Iron deficiency without thrombocytopenia","High INR alone","Low serum albumin"],"correctIndex":0,"explanation":"Platelets support primary haemostasis in selected patients.","explanationNe":"Platelet ले आवश्यक अवस्थामा primary haemostasis सुधार्न मद्दत गर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Fresh frozen plasma contains:","translation":"","options":["Multiple coagulation factors","Only red cells","Only platelets","Pure albumin only"],"correctIndex":0,"explanation":"FFP supplies a broad range of plasma coagulation factors.","explanationNe":"FFP मा विभिन्न coagulation factor हुन्छन्।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"Cryoprecipitate is particularly rich in:","translation":"","options":["Fibrinogen","Sodium","Red cell antigens","Neutrophils"],"correctIndex":0,"explanation":"Cryoprecipitate contains concentrated fibrinogen, factor VIII, factor XIII and von Willebrand factor.","explanationNe":"Cryoprecipitate मा fibrinogen धेरै हुन्छ, साथै केही clotting factor पनि हुन्छन्।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"The usual anticoagulant-preservative solution in a standard blood collection bag is:","translation":"","options":["CPDA-1","EDTA only","Sodium fluoride","Lithium heparin"],"correctIndex":0,"explanation":"CPDA-1 contains citrate, phosphate, dextrose and adenine to preserve collected blood.","explanationNe":"CPDA-1 मा citrate, phosphate, dextrose र adenine हुन्छन्।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"The main function of citrate in blood collection bags is to:","translation":"","options":["Bind calcium and prevent clotting","Destroy red cells","Increase platelet activation","Stain leukocytes"],"correctIndex":0,"explanation":"Citrate chelates calcium, which is required for coagulation.","explanationNe":"Citrate ले coagulation का लागि चाहिने calcium बाँधेर clot हुन दिँदैन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"The usual storage temperature for red-cell components is:","translation":"","options":["2–6°C","20–24°C","−20 to −30°C","37°C"],"correctIndex":0,"explanation":"Red cells are stored refrigerated within the validated range specified by the blood service.","explanationNe":"RBC component लाई blood service ले तोकेको validated २–६°C दायरामा राखिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"Platelet components are generally stored at:","translation":"","options":["20–24°C with continuous gentle agitation","2–6°C without movement","−80°C","37°C"],"correctIndex":0,"explanation":"Platelets are stored at controlled room temperature with agitation according to standards.","explanationNe":"Platelet लाई नियन्त्रित कोठाको तापक्रममा निरन्तर हल्का agitation सहित राखिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"A haemolytic transfusion reaction may result from:","translation":"","options":["ABO-incompatible red-cell transfusion","Transfusion of compatible saline","Normal donor identification","Correctly stored sterile tubing"],"correctIndex":0,"explanation":"ABO incompatibility can cause rapid intravascular haemolysis.","explanationNe":"ABO नमिलेको RBC चढाउँदा छिटो intravascular haemolysis हुन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"The first action when an acute transfusion reaction is suspected is to:","translation":"","options":["Stop the transfusion immediately","Increase the transfusion rate","Discard the patient identification band","Continue until the unit is empty"],"correctIndex":0,"explanation":"Stop the transfusion, maintain IV access with saline using new tubing, and urgently assess the patient according to protocol.","explanationNe":"Reaction शंका भए तुरुन्त transfusion रोक्ने, नयाँ tubing बाट saline सहित IV access कायम राख्ने र protocol अनुसार बिरामी जाँच्ने।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"A febrile non-haemolytic transfusion reaction commonly presents with:","translation":"","options":["Fever and chills during or after transfusion","Severe localised bone fracture","Isolated jaundice months later only","Low blood glucose only"],"correctIndex":0,"explanation":"Fever and chills without evidence of haemolysis may occur due to cytokines or leukocyte antibodies.","explanationNe":"Haemolysis बिना ज्वरो र काम्ने लक्षण cytokine वा leukocyte antibody का कारण हुन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"The main purpose of donor screening is to:","translation":"","options":["Protect both donor and recipient","Guarantee that every donation has no possible risk","Replace laboratory testing","Increase collection volume"],"correctIndex":0,"explanation":"Donor selection assesses health and risk factors to protect donor safety and reduce recipient risk.","explanationNe":"Donor screening ले donor को सुरक्षा र recipient मा संक्रमण/अन्य जोखिम कम गर्न मद्दत गर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-practice-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"A blood donation should be rejected or deferred when:","translation":"","options":["The donor does not meet current eligibility criteria","The donor asks a question","The donor has eaten breakfast","The donor arrives on time"],"correctIndex":0,"explanation":"Eligibility criteria and deferral rules must be applied consistently by trained staff.","explanationNe":"प्रशिक्षित staff ले हालको eligibility र deferral मापदण्ड लागू गर्नुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"A patient with group A positive blood needs red cells. Which listed unit is ABO/Rh compatible?","translation":"","options":["A positive","B positive","AB negative","O positive only is compatible"],"correctIndex":0,"explanation":"A-positive recipients can generally receive A or O red cells that are Rh-compatible, subject to crossmatch and policy.","explanationNe":"A positive बिरामीले सामान्यतया A वा O Rh-compatible RBC लिन सक्छ; crossmatch र policy अनिवार्य हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"A group O patient is mistakenly issued group A red cells. The main danger is:","translation":"","options":["Recipient anti-A causing acute haemolysis","Donor anti-B destroying recipient platelets","Iron deficiency","Vitamin K toxicity"],"correctIndex":0,"explanation":"Group O recipients generally have anti-A and anti-B, so A cells can trigger severe haemolysis.","explanationNe":"O समूहको बिरामीमा anti-A हुने भएकाले A RBC चढाउँदा गम्भीर haemolysis हुन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A crossmatch is incompatible. What should the laboratory do?","translation":"","options":["Do not issue the unit; investigate the incompatibility","Issue it if the bag looks normal","Change the patient''s blood group","Ignore the result in an emergency"],"correctIndex":0,"explanation":"An incompatible result requires investigation and resolution before routine issue.","explanationNe":"Crossmatch नमिलेको unit issue गर्नु हुँदैन; कारण जाँचेर समाधान गर्नुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"A patient has a positive antibody screen. The next appropriate step is generally to:","translation":"","options":["Identify the antibody and select antigen-negative compatible units","Ignore the screen","Issue any ABO-compatible unit without further review","Repeat only the haemoglobin"],"correctIndex":0,"explanation":"Clinically significant antibodies require identification and appropriate antigen-negative selection.","explanationNe":"महत्वपूर्ण antibody भए पहिचान गरी सम्बन्धित antigen नभएको compatible unit छानिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A pregnant Rh-negative woman has anti-D detected. This finding is important because it may:","translation":"","options":["Cause haemolytic disease of the fetus and newborn","Cause ABO typing to become unnecessary","Prevent all infections","Increase maternal platelet count"],"correctIndex":0,"explanation":"Maternal anti-D can cross the placenta and destroy fetal D-positive red cells.","explanationNe":"आमाको anti-D placenta पार गरेर D-positive भ्रूणको RBC नष्ट गर्न सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"A DAT is positive in a patient with suspected immune haemolysis. This means:","translation":"","options":["Red cells are coated with immunoglobulin and/or complement in vivo","The patient has no antibodies","The donor unit is sterile","Platelet count is high"],"correctIndex":0,"explanation":"A positive DAT supports immune coating of red cells, interpreted with clinical and laboratory findings.","explanationNe":"Positive DAT ले शरीरभित्र RBC मा immunoglobulin वा complement लागेको संकेत गर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"A blood bag has a visible leak. The correct action is to:","translation":"","options":["Quarantine and do not transfuse the unit","Seal it with adhesive tape and issue","Transfer contents to another bag","Warm it and inspect later"],"correctIndex":0,"explanation":"A leaking unit may be contaminated and must not be transfused.","explanationNe":"चुहिएको blood bag दूषित हुन सक्छ, transfuse गर्नु हुँदैन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"A red-cell unit is found outside its validated temperature range for an unknown period. The staff should:","translation":"","options":["Quarantine it and seek blood bank quality/safety guidance","Return it to the refrigerator and issue immediately","Ignore the temperature excursion","Mix it with another unit"],"correctIndex":0,"explanation":"Temperature excursions require documented assessment under the blood service procedure.","explanationNe":"तापक्रम सीमा बाहिर गएको unit लाई quarantine गरी documented assessment गर्नुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"A patient develops dyspnoea, hypoxia and bilateral pulmonary oedema during transfusion without evidence of circulatory overload. Consider:","translation":"","options":["Transfusion-related acute lung injury (TRALI)","Iron deficiency","Delayed haemolytic reaction only","Mild urticaria"],"correctIndex":0,"explanation":"TRALI is acute hypoxaemic pulmonary oedema temporally related to transfusion and requires urgent care.","explanationNe":"Transfusion सँग सम्बन्धित acute hypoxia र pulmonary oedema TRALI हुन सक्छ; तुरुन्त उपचार चाहिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"An elderly patient develops hypertension, breathlessness and fluid overload during transfusion. Consider:","translation":"","options":["Transfusion-associated circulatory overload (TACO)","TRALI in every case","Acute iron deficiency","Delayed serologic reaction"],"correctIndex":0,"explanation":"TACO is volume overload associated with transfusion, often with hypertension and pulmonary oedema.","explanationNe":"TACO मा transfusion का कारण volume overload, hypertension र pulmonary oedema हुन सक्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A patient develops itching and hives during transfusion but remains haemodynamically stable. This may be:","translation":"","options":["Mild allergic transfusion reaction","Acute ABO haemolysis confirmed","Bacterial sepsis confirmed","TRALI confirmed"],"correctIndex":0,"explanation":"Urticaria and itching can represent an allergic reaction; stop and assess according to protocol.","explanationNe":"चिलाउने र डाबर उठ्ने mild allergic reaction हुन सक्छ; protocol अनुसार transfusion रोक्दै मूल्याङ्कन गर्नुहोस्।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"A unit is suspected of causing bacterial contamination and the patient has rigors and hypotension. The laboratory should:","translation":"","options":["Stop transfusion and arrange appropriate cultures and investigation","Restart the same unit slowly","Discard all records","Give another unit without assessment"],"correctIndex":0,"explanation":"Septic transfusion reactions require urgent clinical management, cultures and blood bank investigation.","explanationNe":"Septic reaction मा तुरुन्त उपचार, culture र blood bank investigation आवश्यक हुन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A patient needs rapid massive transfusion. The best practice is to:","translation":"","options":["Activate the institutional massive transfusion protocol","Select units by bag colour","Skip identification checks","Use expired components first"],"correctIndex":0,"explanation":"A defined protocol coordinates component support, monitoring and compatibility procedures.","explanationNe":"Massive transfusion protocol ले component, monitoring र compatibility प्रक्रिया समन्वय गर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"A group AB patient requires plasma. Which ABO plasma is generally compatible?","translation":"","options":["AB plasma","O plasma only","A plasma only","B plasma only"],"correctIndex":0,"explanation":"AB plasma contains neither anti-A nor anti-B and is the universal ABO plasma type.","explanationNe":"AB plasma मा anti-A र anti-B हुँदैन, त्यसैले ABO प्रणालीमा universal plasma हो।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"A patient has severe thrombocytopenia and active bleeding. Which component may be indicated?","translation":"","options":["Platelet concentrate","Packed red cells only","Cryoprecipitate only","Albumin only"],"correctIndex":0,"explanation":"Platelet transfusion may be indicated depending on count, cause, bleeding and clinical protocol.","explanationNe":"Platelet count, कारण र bleeding अवस्था हेरेर platelet concentrate दिन सकिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"A patient with low fibrinogen and major bleeding requires replacement. Which component is particularly useful?","translation":"","options":["Cryoprecipitate or fibrinogen concentrate according to protocol","Washed red cells","Platelet-poor plasma only","Normal saline only"],"correctIndex":0,"explanation":"Cryoprecipitate is rich in fibrinogen and may be used when indicated by local protocol.","explanationNe":"Cryoprecipitate मा fibrinogen धेरै हुन्छ; protocol अनुसार प्रयोग गरिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"A blood donor feels faint after donation. The immediate response should include:","translation":"","options":["Stop collection if ongoing, lay the donor safely and assess","Ask the donor to stand quickly","Leave the donor alone","Continue collection regardless"],"correctIndex":0,"explanation":"Vasovagal reactions require safe positioning, observation and assessment.","explanationNe":"Donor लाई बेहोसजस्तो भए सुरक्षित सुताएर observation र assessment गर्नुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"A donor''s haemoglobin is below the accepted threshold. What is appropriate?","translation":"","options":["Defer donation and advise according to donor policy","Collect a full unit anyway","Dilute the sample","Change the haemoglobin result"],"correctIndex":0,"explanation":"Donor haemoglobin criteria protect the donor from donation-related harm.","explanationNe":"कम haemoglobin हुँदा donor को सुरक्षाका लागि donation स्थगित गरिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"A blood unit is returned from the ward after being issued but not transfused. It should be:","translation":"","options":["Managed under validated return-to-stock time and temperature policy","Automatically returned to stock","Kept at room temperature overnight","Issued to another patient immediately"],"correctIndex":0,"explanation":"Returned units can only be re-stocked if traceability and validated conditions are met.","explanationNe":"फिर्ता आएको unit पुनः stock मा राख्न validated समय, तापक्रम र traceability मापदण्ड पूरा हुनुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"A clerical mismatch is found between the patient''s wristband and blood sample label. What is safest?","translation":"","options":["Stop the process and recollect/resolve identity according to policy","Correct the label from memory","Use the bed number instead","Proceed if ABO group is known"],"correctIndex":0,"explanation":"Identification errors are a major preventable cause of wrong-blood events.","explanationNe":"Patient र sample label नमिलेमा प्रक्रिया रोक्दै policy अनुसार पहिचान मिलाउनुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"A blood bank refrigerator alarm indicates temperature above range. The first step is to:","translation":"","options":["Keep stock secure, assess and document the excursion per SOP","Switch off the alarm","Issue all units quickly","Open the door repeatedly"],"correctIndex":0,"explanation":"Temperature excursions require prompt response, documentation and product disposition assessment.","explanationNe":"Refrigerator तापक्रम बढेमा stock सुरक्षित राखी SOP अनुसार जाँच र अभिलेख गर्नुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"A quality control sample fails in blood grouping testing. What should happen?","translation":"","options":["Hold affected results and investigate before reporting","Report patient groups anyway","Change control values manually","Ignore the failed control"],"correctIndex":0,"explanation":"Failed QC means test validity is uncertain until the cause is resolved.","explanationNe":"QC fail हुँदा कारण समाधान नभएसम्म सम्बन्धित patient result report गर्नु हुँदैन।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"A transfusion reaction is reported after the unit has finished. What is the appropriate action?","translation":"","options":["Notify the clinical team and investigate according to reaction protocol","Assume it cannot be transfusion-related","Discard the empty bag immediately without review","Change the patient''s blood group"],"correctIndex":0,"explanation":"Delayed reactions still require clinical assessment and blood bank investigation.","explanationNe":"Transfusion सकिएपछि reaction देखिए पनि clinical assessment र blood bank investigation चाहिन्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"A patient has a clinically significant anti-K antibody. Which donor red-cell unit should be selected?","translation":"","options":["K-antigen-negative compatible unit","K-positive unit regardless of crossmatch","Any unit without ABO typing","Only platelet concentrate"],"correctIndex":0,"explanation":"Patients with anti-K should receive K-negative red cells that are otherwise compatible.","explanationNe":"Anti-K भएको बिरामीलाई K antigen नभएको compatible RBC दिनुपर्छ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true),
('bmlt-bloodbank1-mock-025','BMLT','BMLT NHPC Licensing','mock','free',25,'{"question":"The blood bank records donor, component, recipient and issue details mainly to ensure:","translation":"","options":["Full traceability and haemovigilance","Faster staining of blood films","Higher donor weight","Avoidance of compatibility testing"],"correctIndex":0,"explanation":"Traceability supports recalls, reaction investigations and haemovigilance.","explanationNe":"Traceability ले recall, reaction investigation र haemovigilance सम्भव बनाउँछ।","topic":"Blood Banking & Transfusion Medicine"}'::jsonb,true)
